import{_ as e,c as t,o as i,ae as r}from"./chunks/framework.CHDT0Kbg.js";const _=JSON.parse('{"title":"认识 Persim","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1795170900000}'),l={name:"zh-CN/guide/introduction.md"};function o(n,a,s,d,h,c){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="认识-persim" tabindex="-1">认识 Persim <a class="header-anchor" href="#认识-persim" aria-label="Permalink to &quot;认识 Persim&quot;">​</a></h1><p>一个打开就能用的 Mac 浏览器：标签、搜索、书签、下载，都在该在的位置。</p><h2 id="打开就会做什么" tabindex="-1">打开就会做什么 <a class="header-anchor" href="#打开就会做什么" aria-label="Permalink to &quot;打开就会做什么&quot;">​</a></h2><ul><li><strong>上网与搜索</strong>：地址栏既能输入网址，也能直接搜索；常去的地址会优先补全。</li><li><strong>多个标签与窗口</strong>：新建、拖动、分组、静音、悬停预览，按 ⌘⇧A 快速找到某个标签。</li><li><strong>收藏与找回</strong>：书签栏、书签管理器、历史记录、下载中心，还有「恢复上次会话」。</li></ul><h2 id="想安静一点" tabindex="-1">想安静一点 <a class="header-anchor" href="#想安静一点" aria-label="Permalink to &quot;想安静一点&quot;">​</a></h2><ul><li>广告拦截支持订阅规则、自定义规则和白名单，信任的站点可以放行。</li><li>网页强制深色、标签静音、弹窗拦截都在设置里一键开关。</li><li>无痕窗口（⌘⇧N）不会写下浏览历史。</li></ul><h2 id="看视频与读长文" tabindex="-1">看视频与读长文 <a class="header-anchor" href="#看视频与读长文" aria-label="Permalink to &quot;看视频与读长文&quot;">​</a></h2><ul><li>嗅探面板列出页面里的视频，保存后就是一个完整的 MP4，用你习惯的应用打开即可。</li><li>阅读模式（⌘⇧R）去掉导航和广告，只留下正文；还可以截可视区或整页 PDF。</li></ul><h2 id="按你的习惯来" tabindex="-1">按你的习惯来 <a class="header-anchor" href="#按你的习惯来" aria-label="Permalink to &quot;按你的习惯来&quot;">​</a></h2><p>浅色 / 深色 / 跟随系统，六种主色，书签栏三种显示方式，界面语言 25 种。外观改完立刻生效，界面语言需要重新打开窗口。</p>',10)])])}const m=e(l,[["render",o]]);export{_ as __pageData,m as default};
